import itertools, collections

def canon_D4(sub):
    trans=[]
    for t in range(8):
        arr=[]
        for r,c in sub:
            x,y=r,c
            if t>=4: y=-y
            for _ in range(t%4): x,y=y,-x
            arr.append((x,y))
        mr=min(x for x,y in arr); mc=min(y for x,y in arr)
        trans.append(tuple(sorted((x-mr,y-mc) for x,y in arr)))
    return min(trans)
